  const archived=projects.filter(project=>projectIsArchived(project)),lastEvent=safe(current.projectData.history).at(-1),health=globalThis.closedLoopStorageHealth||{},lastBackup=projectStorage.lastBackup?{at:projectStorage.lastBackup}:null;
