function stabilityMarkup(n){if(![13,18,19].includes(n))return '';const iteration=engine.records(current,'iterations').filter(r=>engine.isActiveRecord(r)).at(-1),id=iteration?engine.recordId(iteration,'iterations'):null;if(!id)return '';const m=engine.executionStability(current,id),reqs=Object.values(m.requirementStability),complete=reqs.filter(x=>x.agreementRate===1).length,disagree=reqs.length-complete,violated=reqs.filter(x=>x.violated>0).length,undetermined=reqs.filter(x=>x.undetermined>0).length;return `<div class="panel"><h2 class="section-title">Execution stability</h2><div class="stage-action-strip"><span>${m.runCount}/10 runs</span><span>Complete agreement: <strong>${complete}/${reqs.length}</strong></span><span>Disagreement: <strong>${disagree}</strong></span><span>Violation: <strong>${violated}</strong></span><span>Undetermined: <strong>${undetermined}</strong></span></div>${details('New defects by run',m.newDefectsByRun,true)}</div>`;}
