function reviewerContextMarkup(n,locked){if(!reviewerOperation(n)||(locked&&n!==9))return '';const ctx=currentReviewerContext(n),external=ctx?String(engine.recordValue(ctx,'EXTERNAL_CONTEXT_IDENTIFIER')||'').trim():'',preflight=n===9,runReview=n===12||([17,19].includes(n)&&selectedOperation(n)==='VERIFY'),reference=preflight?'the context that authored the Stage 08 production instruction':runReview?'the production context that generated the selected run':'the Stage 21 product-generation context';if(ctx&&external)return `<div class="notice success"><strong>Independent reviewer context registered.</strong><br>${esc(engine.recordId(ctx,'freshContexts'))} · ${esc(external)}. The controlling prompt is bound to this reviewer context and must not reuse ${esc(reference)}.</div>`;return `<div class="panel" id="reviewer-context-required" tabindex="-1"><h2 class="section-title">Open a fresh independent reviewer context</h2><p class="section-intro">Use a new external conversation/context that did not perform ${preflight?'Stage 08 instruction authoring':runReview?'the selected run generation':'product generation'}. Enter its identifier here before saving or copying the reviewer instruction; the application binds that identity into the controlling prompt.</p><div class="field"><label>Fresh reviewer context identifier</label><input id="fresh-context-id" autocomplete="off"${locked?' disabled':''}><span class="help">Use the external conversation/session identifier you can recognize later. Do not reuse ${esc(reference)}.</span></div><div class="button-row"><button class="primary" id="add-fresh-context" type="button"${locked?' disabled':''}>Register reviewer context</button></div></div>`;}
function stagePurposeMarkup(n){const text={4:'The application supplies the complete Stage 04 obligation manifest from the current User Job Input, accepted Stage 01 capture, and accepted Stage 03 research. No original Stage 01 intent file is required here. If required upstream canonical data is incomplete, this stage remains unavailable until the deficient earlier stage is completed.',6:'AI is creating verification tests now. Test definition is not execution.',7:'Invalid examples are being created and actually checked so a validator cannot appear reliable without rejecting known-invalid cases.',10:'Select the exact verified files that make up this candidate. The application freezes their identities and hashes.',11:'The same frozen candidate is executed 10 times in independent fresh contexts.',12:'Each run is checked against the stored tests. Verifiers must remain independent from the generating run.',15:'Every confirmed defect becomes a permanent regression: definition, reproduced failure, later correction proof, and active future protection remain distinct.',16:'Fix the earliest controlled thing that caused each confirmed defect. The application preserves the old version, handles IDs/versions/hashes, and determines what must be repeated. Execution-only failures do not trigger unsupported specification edits.',17:'The corrected candidate is rerun through the complete ten-execution verification loop.',19:'The unchanged final candidate is rerun in ten new contexts to confirm stability without changing the candidate.',21:'The approved final product is created from the baseline. These exact stored output bytes become the product under test.',22:'The exact finished-product bytes are checked by the executor declared in each deterministic test. The application never invents execution that did not occur.',23:'Requirements needing meaning judgment go to an independent reviewer with only the context needed for that comparison.',24:'The finished product is deliberately challenged for failures and regressions without feeding the reviewer prior conclusions.',25:'The exact delivery files and required rendered/package representations are inspected.',26:'Process evidence and product evidence are reconciled as separate propositions.',27:'The application calculates whether release is allowed. Neither the agent nor the operator sets the release state.',28:'No external agent response is used here. Open Release control and select the exact audited canonical files and exact delivery files; the application computes and compares byte size and SHA-256 before authorization.',29:'The application proves every mandatory requirement has a current structural evidence chain and evidence capable of proving the proposition.'}[n];const automatic=n===22&&nativeStage22Tests().length?`<div class="button-row"><button class="primary" id="run-native-tests" type="button">Run ${nativeStage22Tests().length} automatic test${nativeStage22Tests().length===1?'':'s'}</button></div>`:'',external=stagePlanItems(n,selectedOperation(n)).some(item=>item.executionMode!=='APPLICATION_DETERMINISTIC'&&item.operatorAction!=='NO_ACTION'&&item.operatorAction!=='BLOCKED')?`<div class="button-row"><button id="download-execution-package" type="button">Download verification package</button></div>`:'';return text?`<div class="notice"><strong>This stage</strong><br>${esc(text)}${n===28?'<div class="button-row"><button class="primary" type="button" data-view="Release">Open release controls</button></div>':''}${automatic}${external}</div>`:(automatic+external);}
function provenanceAnchor(kind,id){return `provenance-${kind}-${String(id||'UNKNOWN').replace(/[^A-Za-z0-9_-]+/g,'-')}`;}
function provenanceMarkup(n){
  const manifests=safe(current.projectData.extractionManifests).filter(m=>Number(m.stage)===n),rawById=new Map(safe(current.projectData.rawResponses).map(x=>[String(x.rawResponseId||''),x])),promptById=new Map(safe(current.projectData.generatedPrompts).map(x=>[String(x.instructionId||x.promptId||''),x])),evidenceById=new Map(engine.records(current,'evidenceRecords').map(x=>[String(engine.recordId(x,'evidenceRecords')||''),x])),usedRaw=new Set(),usedPrompts=new Set(),usedEvidence=new Set();
  const cards=manifests.flatMap(m=>safe(m.entries||m.changes).map(e=>{const rawId=String(m.rawResponseId||m.RAW_RESPONSE_ID||''),promptId=String(m.promptId||m.PROMPT_ID||''),evidenceIds=safe(e.evidenceIds).map(String),name=`${e.canonicalCollection||e.canonicalRecordType||''}/${e.canonicalRecordId||''}/${e.canonicalField||e.canonicalRelationship||''}`;if(rawId)usedRaw.add(rawId);if(promptId)usedPrompts.add(promptId);evidenceIds.forEach(id=>usedEvidence.add(id));const links=[rawId&&rawById.has(rawId)?`<a href="#${esc(provenanceAnchor('raw',rawId))}">Preserved raw response</a>`:'',promptId&&promptById.has(promptId)?`<a href="#${esc(provenanceAnchor('prompt',promptId))}">Controlling prompt</a>`:'',...evidenceIds.filter(id=>evidenceById.has(id)).map(id=>`<a href="#${esc(provenanceAnchor('evidence',id))}">Evidence ${esc(id)}</a>`)].filter(Boolean).join(' · ');return `<details class="record-card provenance-trace"><summary>${esc(name)}<span>Trace</span></summary><div class="record-body"><p class="section-intro">Canonical field → extraction manifest → exact response pointer → preserved raw response → controlling prompt → canonical evidence.</p><p class="compact-provenance-targets">Preserved raw response: ${esc(rawId||'NONE')} · Controlling prompt: ${esc(promptId||'NONE')} · Canonical evidence: ${esc(evidenceIds.length?evidenceIds.join(', '):'NONE')}</p>${details('Extraction manifest and response pointer',{manifestId:m.manifestId,responsePointer:e.jsonPointer||e.JSON_POINTER_IN_RESPONSE||'',rawResponseId:rawId||'NONE',promptId:promptId||'NONE',evidenceIds},true)}${links?`<div class="notice provenance-links">${links}</div>`:'<div class="notice warn">One or more provenance targets are unavailable for this trace.</div>'}</div></details>`;}));
  if(!cards.length)return '';
  const rawLookups=[...usedRaw].map(id=>rawById.get(id)).filter(Boolean).map(raw=>`<div id="${esc(provenanceAnchor('raw',raw.rawResponseId))}">${details(`Preserved raw response — ${raw.rawResponseId}`,raw)}</div>`).join('');
  const promptLookups=[...usedPrompts].map(id=>promptById.get(id)).filter(Boolean).map(prompt=>{const id=prompt.instructionId||prompt.promptId;return `<div id="${esc(provenanceAnchor('prompt',id))}">${details(`Controlling prompt — ${id}`,prompt)}</div>`;}).join('');
  const evidenceLookups=[...usedEvidence].map(id=>evidenceById.get(id)).filter(Boolean).map(record=>{const id=engine.recordId(record,'evidenceRecords');return `<div id="${esc(provenanceAnchor('evidence',id))}">${details(`Canonical evidence — ${id}`,record)}</div>`;}).join('');
  return `<details class="record-card" id="provenance-navigation" tabindex="-1"><summary>Provenance navigation<span>${cards.length} trace${cards.length===1?'':'s'}</span></summary><div class="record-body"><p class="section-intro">Each accepted field points to shared provenance targets. Large raw responses and prompts are rendered once per source record instead of being duplicated inside every field trace.</p>${cards.join('')}<details class="record-card provenance-targets"><summary>Provenance source records<span>${usedRaw.size+usedPrompts.size+usedEvidence.size}</span></summary><div class="record-body">${rawLookups}${promptLookups}${evidenceLookups}</div></details></div></details>`;
}
