function downloadRawRecovery(text,prompt,error,transport=null){const payload={schema:'closed-loop-raw-response-recovery/1',failedOperation:'RAW_CAPTURE',canonicalStateChanged:false,jobId:current?.job?.JOB_ID||null,stage:current?.activeStage||null,promptIdentity:prompt?{instructionId:prompt.instructionId||prompt.promptId,bodySha256:prompt.bodySha256||prompt.sha256,contractSha256:prompt.contractSha256,contextSignature:prompt.contextSignature}:null,transport:transport?{stagingId:transport.stagingId,rawFilename:transport.rawFilename,byteSize:transport.byteSize,sha256:transport.sha256,authority:transport.authority}:null,error:String(error?.message||error),rawResponse:String(text??'')},blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${current?.job?.JOB_ID||'project'}-raw-response-recovery.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),0);}
async function prepareStageResponseFile(file,{nonauthoritativeFallback=false}={}){
  const n=current.activeStage;if(!(file instanceof Blob)){alert('Select the authoritative response JSON file first.');return;}let staged,verified,text,prompt,captured;
  try{
    staged=await projectStore.stageResponseFile({jobId:current.job.JOB_ID,stage:n,blob:file,rawFilename:file.name||'response.json',mediaType:file.type||'application/json'});
    verified=await projectStore.readStagedResponseFile({jobId:current.job.JOB_ID,stagingId:staged.stagingId});
    const bytes=verified.bytes;if(bytes[0]===0xef&&bytes[1]===0xbb&&bytes[2]===0xbf)throw Object.assign(new Error('The authoritative response JSON file must be UTF-8 without a BOM.'),{code:'RESPONSE_FILE_BOM'});
    text=new TextDecoder('utf-8',{fatal:true}).decode(bytes);
    if(globalThis.closedLoopHash.sha256Text(text)!==verified.sha256)throw Object.assign(new Error('Decoded response text does not reproduce the exact selected response-file bytes.'),{code:'RESPONSE_FILE_DECODE_HASH_MISMATCH'});
    prompt=responsePromptRecord(n,text);if(!prompt)throw new Error('No saved instruction matches this response file. Save/export the current instruction, run that exact instruction in the external context, then select its final response JSON file.');
    const transport={authority:nonauthoritativeFallback?'NONAUTHORITATIVE_TEXT_FALLBACK':'AUTHORITATIVE_RESPONSE_FILE',materializedAsResponseFile:Boolean(nonauthoritativeFallback),stagingId:verified.stagingId,rawFilename:verified.rawFilename,mediaType:verified.mediaType,byteSize:verified.byteSize,sha256:verified.sha256,status:verified.status};
    captured=ingestion.captureRaw(current,{stage:n,text,promptRecord:prompt,contextId:prompt.scope?.contextId||'UNKNOWN',files:safe(current.stages[n].authorizedFiles),transport});
    captured.project.stages[n].responseDraft='';await persistReplacement(captured.project);announce('response file staged and raw bytes preserved');
  }catch(error){console.error(error);announce('response file staging failed');downloadRawRecovery(text||'',prompt,error,staged||verified||null);alert(`Response-file staging failed. Canonical state did not change. Any successfully staged bytes remain recoverable by their recorded filename and digest: ${error.message||error}`);return;}
  try{const prepared=ingestion.prepareCaptured(current,{rawResponseId:captured.rawRecord.rawResponseId,promptRecord:prompt,expectedCommittedRevision:Number(current.revision||0)+1});await persistReplacement(prepared.project);announce(prepared.validation?.valid?'proposal ready':'validation failed');render();queueMicrotask(()=>$(prepared.validation?.valid?'#proposal-heading':'#validation-report')?.focus());}
  catch(error){console.error(error);announce('storage failed');alert(`The exact response-file bytes were preserved, but validation/proposal storage failed. Canonical state did not change: ${error.message||error}`);}
}
async function prepareStageResponseFallback(){const text=$('#stage-output')?.value||'';if(!text.trim()){alert('Enter diagnostic fallback JSON text first.');return;}const blob=new Blob([new TextEncoder().encode(text)],{type:'application/json'});Object.defineProperty(blob,'name',{value:`${current.job.JOB_ID}_S${String(current.activeStage).padStart(2,'0')}_FALLBACK_RESPONSE.json`});return prepareStageResponseFile(blob,{nonauthoritativeFallback:true});}
