const artifactIdFor=()=>`${String(current.job.JOB_ID||'JOB').replace(/[^A-Za-z0-9-]/g,'')}-ARTIFACT-${crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2,8)}`}`;
